class Solution {
public:
    int maxIceCream(vector<int>& costs, int coins) {
        sort(costs.begin(), costs.end());
        int count = 0;
        for (int c : costs) {
            if (coins >= c) {
                coins -= c;
                count++;
            } else {
                break;
            }
        }
        return count;
    }
};

import java.util.*;

class Solution {
    public int maxIceCream(int[] costs, int coins) {
        Arrays.sort(costs);
        int count = 0;
        for (int c : costs) {
            if (coins >= c) {
                coins -= c;
                count++;
            } else {
                break;
            }
        }
        return count;
    }
}

/**
 * @param {number[]} costs
 * @param {number} coins
 * @return {number}
 */
var maxIceCream = function(costs, coins) {
    costs.sort((a, b) => a - b);
    let count = 0;
    for (const c of costs) {
        if (coins >= c) {
            coins -= c;
            count++;
        } else {
            break;
        }
    }
    return count;
};
